    "opencode",
    "opencode-plugin",
    "ibm",
    "bob",
    "llm-provider"
  ],
  "homepage": "https://github.com/gcoadour/opencode-ibm-bob#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/gcoadour/opencode-ibm-bob.git"
  },
  "bugs": {
    "url": "https://github.com/gcoadour/opencode-ibm-bob/issues"
  },
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
